with cleaned as (select id, session_id, event_type, event_time, duration_sec, date_format(event_time, 'yyyy-MM') as event_time_label, length(event_type) as event_type_length from web_events where page not in ('/checkout', '/home', '/cart')), gaps as (select *, case when event_time - lag(event_time) over (partition by event_type order by event_time asc, id asc) > interval '7' day then 1 else 0 end as new_group_flag from cleaned), islands as (select *, sum(new_group_flag) over (partition by event_type order by event_time asc, id asc rows between unbounded preceding and current row) as session_id_2 from gaps), deduped as (select *, row_number() over (partition by event_type order by event_type_length desc nulls last, id asc) as row_num from islands qualify row_num = 1), remaining_keys as (select id, event_type from deduped except distinct select id, event_type from web_events where event_type != 'click'), reconciled as (select s.* from deduped s inner join remaining_keys k on s.id = k.id and s.event_type = k.event_type), with_dims as (select a.*, b.device from reconciled a left join sessions b on a.session_id = b.id), joined as (select a.*, s.country from with_dims a left join sessions s on a.session_id = s.id), joined_web_events as (select a.*, s.country as session_country, s.browser from joined a left join sessions s on a.session_id = s.id), wide as (select * from (select session_id, browser, session_id_2 from joined_web_events) src pivot (sum(session_id_2) as amount for browser in ('Chrome', 'Firefox', 'Safari'))) select session_id, Firefox, Safari from wide;
